def call_goto(px, py):
    return primitives.call(name='submit_capx_action', action='goto_pose', native_api=True,
                           parameters={'position': [px, py, 0.0], 'quaternion_wxyz': [0, 0, 1, 0]})

def get_obs():
    o = primitives.call(name='observe_capx_scene')
    s = str(o.output)
    try:
        i = s.index("robot0_eef_pos")
        t = s[i:]; t = t[t.index('[') + 1:]; t = t[:t.index(']')]
        vals = [float(p) for p in t.split(',')[:3]]
        j = s.index("proportion_wiped")
        u = s[j:]; u = u[u.index(':') + 1:]; u = u[:u.index(',')]
        return vals, float(u)
    except Exception:
        return None, None

# local inverse map: eef = M*cmd + t  with M=[[0.623,0.047],[-0.043,0.857]], t=(-0.280,-0.019)
def cmd_delta(tx, ty, ox, oy):
    dx = tx - ox; dy = ty - oy
    return (1.599 * dx - 0.0877 * dy, 0.0802 * dx + 1.162 * dy)

obs, pw = get_obs()
print('start obs', obs, 'pw', pw)
cmd = [0.0, -0.30]
xs = [-0.10, -0.033, 0.033, 0.10, 0.165]
rows = [-0.30, -0.22, -0.14, -0.06]
done = False
moves = 0
for ri, ty in enumerate(rows):
    seq = xs if ri % 2 == 0 else xs[::-1]
    for tx in seq:
        if obs is None:
            obs, pw = get_obs()
            continue
        for k in range(2):
            d = cmd_delta(tx, ty, obs[0], obs[1])
            cmd = [cmd[0] + d[0], cmd[1] + d[1]]
            r = call_goto(cmd[0], cmd[1])
            moves += 1
            new_obs, pw = get_obs()
            if new_obs is None:
                break
            obs = new_obs
            res = ((tx - obs[0]) ** 2 + (ty - obs[1]) ** 2) ** 0.5
            if res < 0.04:
                break
        if pw is not None and pw >= 0.95:
            done = True
            break
    print('row', ty, 'pw', pw, 'obs', [round(v, 3) for v in obs] if obs else None)
    if done:
        break
print('moves', moves, 'final pw', pw)
